大きさ $2\theta\ (0<\theta<\frac\pi2)$ の角の2辺に接する円 $O_1$（半径1）をかく．次に，角の2辺と $O_1$ に接し $O_1$ より頂点に近い円 $O_2$，以下同様に $O_3,O_4,\dots$ をかく．円 $O_n$ の半径を $r_n$ とする．
\begin{enumerate}
  \item $r_{n+1}$ を $r_n$ と $\theta$ で表せ．
  \item $2\theta=60^\circ$ のとき，すべての円の面積の和を求めよ．
\end{enumerate}

サイコロを $n$ 回投げるとき，1の目が出る回数が偶数（0回を含む）である確率を $p_n$ とする．
\begin{enumerate}
  \item $p_{n+1}$ を $p_n$ で表せ．
  \item $p_n$ を求めよ．
\end{enumerate}

$f_1(x)=x,\ f_2(x)=x^2-2,\ f_{n+2}(x)=xf_{n+1}(x)-f_n(x)$ で整式 $f_n(x)$ を定める．
\begin{enumerate}
  \item $f_n(2\cos\theta)=2\cos n\theta$ を数学的帰納法で示せ．
  \item $f_n(x)=0$ の解をすべて求めよ．
\end{enumerate}

容量1リットルの $m$ 個のビーカーに水が入っている．$m\geqq4$ で空のビーカーはなく，水の総量は1リットルである．$x$ リットルの水が入ったビーカー X がただ1つあり，他のビーカーには $x$ リットル未満しか入っていない．水の入ったビーカーが2個になるまで次の操作を繰り返す．
\begin{enumerate}
  \item[(a)] 水の量が最も少ないビーカーを1つ選ぶ．
  \item[(b)] 残りの中から水の量が最も少ないものを1つ選ぶ．
  \item[(c)] (a) のビーカーの水を (b) のビーカーにすべて移し，空になったビーカーを取り除く．
\end{enumerate}
（最少のものが複数あるときはいずれも選ばれうる．）
\begin{enumerate}
  \item $x>\dfrac25$ のとき，X は最後まで $x$ リットルのまま残ることを証明せよ．
  \item $m=4$，$x=\dfrac38$ のとき，X が最後まで $x$ リットルのまま残る例と，X の水の量が増える例をそれぞれ1つずつ挙げよ．
\end{enumerate}

1辺の長さ1の立方体 X と球 Y があって，両者の表面積は等しいとする．円周率は $\pi=3.14\cdots$ である．
\begin{enumerate}
  \item X と Y を動かして，X のなるべく多くの頂点が Y の内部に含まれるようにしたい．最大何個の頂点が含まれるようにできるか．
  \item X と Y を動かして，X のなるべく多くの辺が Y の内部と共通の点をもつようにしたい．最大何個の辺が共通の点をもつようにできるか．
\end{enumerate}

$a$ を実数とし，座標平面上の点 $(x,y)$ を点 $(x+y,\ ax+y)$ に移す写像を $f$ とする．
\begin{enumerate}
  \item $f(f(P))=P$ をみたす点Pが原点以外にも存在するような $a$ の値をすべて求めよ．
  \item (1) のそれぞれの $a$ について，そのような点P全体を求めよ．
  \item $f(P)=P$ をみたす点Pが原点以外に存在する $a$ の値を求め，(1) との違いを説明せよ．
\end{enumerate}

$a,b,c,d$ を整数とする．有理数 $r,s$ に対して
\[\Delta(r,s)=(r+sa)(r+sd)-s^2bc\]
とおき，次の条件 (＊) を考える．
\begin{center}
(＊)\quad 有理数 $r,s$ について，4つの数 $r+sa,\ sb,\ sc,\ r+sd$ の少なくとも1つが0でなければ，$\Delta(r,s)\neq0$ である．
\end{center}
\begin{enumerate}
  \item (＊) が成り立つための $a,b,c,d$ についての必要十分条件を求めよ．
  \item $a,b,c,d$ がそれぞれ $0,1,2$ のいずれかであるような81個の組 $(a,b,c,d)$ のうち，(＊) をみたすものの個数を求めよ．
\end{enumerate}

以下，$\sqrt2,\ \sqrt5,\ \sqrt{10}$ が無理数であることは用いてよい．
\begin{enumerate}
  \item 有理数 $p,q,r,w$ について，$p+q\sqrt2+r\sqrt5+w\sqrt{10}=0$ ならば $p=q=r=w=0$ であることを示せ．
  \item 実数係数の2次式 $f(x)=x^2+ax+b$ について，$f(2)$，$f(\sqrt2)$，$f(1+\sqrt5)$ のうち少なくとも1つは無理数であることを示せ．
\end{enumerate}

実数 $a,b,c,d,r,s$ が次の (i)〜(iii) をみたすとする．
\begin{itemize}
  \item[(i)] $|s|>1$
  \item[(ii)] $ar+b=sr$，$cr+d=s$
  \item[(iii)] $x_0=1$，$y_0=0$，$x_{n+1}=ax_n+by_n$，$y_{n+1}=cx_n+dy_n$（$n=0,1,2,\cdots$）で数列 $\{x_n\},\ \{y_n\}$ を定めるとき，ある正の数 $M$ があって，すべての $n$ で $|x_n|\leqq M$，$|y_n|\leqq M$．
\end{itemize}
$z_n=x_n-ry_n$，$w_n=y_n$ とおく．
\begin{enumerate}
  \item $z_{n+1},\ w_{n+1}$ を $z_n,\ w_n$ と $a,\ c,\ r,\ s$ を用いて表せ．
  \item ある正の数 $L$ があって，すべての $n$ で $|z_n|\leqq L$，$|w_n|\leqq L$ となることを示せ．
  \item $c=0$ かつ $|a|\leqq1$ を示せ．
  \item $r=2,\ s=-3$ のとき，(i)〜(iii) をみたす $(a,b,c,d)$ をすべて求めよ．
\end{enumerate}

ベクトル $\vec v=(x,y)$ に対して $f(\vec v)=(x+y,\ 4x+y)$ と定める．また，実数の定数 $p,q,r,s$ を用いて $g(\vec v)=(px+qy,\ rx+sy)$ と表される対応 $g$ を考える．$f(f(\vec v))$ を $f^2(\vec v)$，$g(g(\vec v))$ を $g^2(\vec v)$ と書く．
\begin{enumerate}
  \item すべての $\vec v$ で $f(g(\vec v))=g(f(\vec v))$ ならば，すべての $\vec v$ で $g(\vec v)=kf(\vec v)+l\vec v$ となる実数 $k,\ l$ が存在することを示せ．
  \item すべての $\vec v$ で $f(g(\vec v))=g(f(\vec v))$ かつ $g^2(\vec v)=\vec0$ ならば，すべての $\vec v$ で $g(\vec v)=\vec0$ であることを示せ．
  \item すべての $\vec v$ で $f(g(\vec v))=g(f(\vec v))$ かつ $g^2(\vec v)=f^2(\vec v)$ をみたす $g$ をすべて求めよ．
\end{enumerate}

$\varphi(t)=\dfrac t{1+t}$（$t\geqq0$）とする．
\begin{enumerate}
  \item $x,y\geqq0$ のとき，$\varphi(x+y)\leqq\varphi(x)+\varphi(y)$ を示せ．
  \item 実数 $a,b,c$ に対して $\varphi(|a-c|)\leqq\varphi(|a-b|)+\varphi(|b-c|)$ を示せ．
  \item $a\leqq b\leqq c$ を満たすすべての実数 $a,b,c$ に対して
  \[
  \varphi(c-a)\geqq k\{\varphi(b-a)+\varphi(c-b)\}
  \]
  が成り立つような定数 $k$ の最大値を求めよ．
\end{enumerate}

$a,b,c$ を正の定数とする．座標空間で，$x$ 軸，$y$ 軸，$z$ 軸の正の部分にそれぞれ点 $\mathrm P(p,0,0)$，$\mathrm Q(0,q,0)$，$\mathrm R(0,0,r)$ をとり，平面 PQR が原点 O を中心とする半径1の球面に接するように動かす．
\begin{enumerate}
  \item $a\,\mathrm{OP}^2+b\,\mathrm{OQ}^2+c\,\mathrm{OR}^2$ の最小値を $a,b,c$ で表せ．
  \item 四面体 OPQR の体積の最小値を求めよ．
\end{enumerate}

$p,q$ を正の実数とする．座標空間の3点 $\mathrm P(p,0,0)$，$\mathrm Q(0,q,0)$，$\mathrm R(0,0,1)$ が $\angle\mathrm{PRQ}=\dfrac\pi6$ を満たしている．O を原点とする．
\begin{enumerate}
  \item O と平面 PQR の距離の最大値を求めよ．
  \item $p+q$ のとりうる値の範囲を求めよ．
\end{enumerate}

区間 $[a,b]$（$a<b$）が関数 $h(x)$ に関して不変であるとは，「$a\leqq x\leqq b$ ならば $a\leqq h(x)\leqq b$」が成り立つことをいう．$f(x)=x^2-2$，$g(x)=4x(1-x)$ とする．
\begin{enumerate}
  \item 区間 $[-2,2]$ は $f$ に関して不変であることを示せ．
  \item $f$ に関して不変な区間 $[a,b]$（$a<b$）は $[-2,2]$ のみであることを示せ．
  \item $\psi(u)=2-4u$ とおくと $f(\psi(u))=\psi(g(u))$ が成り立つことを示し，$g$ に関して不変な区間 $[a,b]$（$a<b$）をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 整数 $x,\ y,\ z$ が $x+y\sqrt2+z\sqrt3=0$ をみたすならば $x=y=z=0$ であることを示せ．
  \item 任意の正の整数 $N$ に対して，$|y|\leqq N,\ |z|\leqq N,\ (y,z)\neq(0,0)$ であり
  \[
  0<|x+y\sqrt2+z\sqrt3|<\frac1{N(N+2)}
  \]
  をみたす整数 $x,\ y,\ z$ が存在することを示せ．
  \item $|y|\leqq2,\ |z|\leqq2,\ (y,z)\neq(0,0)$ をみたす整数 $x,\ y,\ z$ のうち，$|x+y\sqrt2+z\sqrt3|$ を最小にするものをすべて求めよ．ただし $\sqrt2=1.41421\cdots$，$\sqrt3=1.73205\cdots$ を用いてよい．
\end{enumerate}

曲線 $C:y=x^3\ (x\geqq0)$ 上の点 P と，直線 $\ell:y=3x-5$ の距離を考える．
\begin{enumerate}
  \item P の $x$ 座標を $t\ (t\geqq0)$ とするとき，P と $\ell$ の距離を $t$ の式で表せ．
  \item P と $\ell$ の距離の最小値と，そのときの P の座標を求めよ．
\end{enumerate}

3で割ると2余り，5で割ると3余る自然数を小さい順に並べてできる数列を $\{a_n\}$ とする．
\begin{enumerate}
  \item $a_1$ と，一般項 $a_n$ を求めよ．
  \item $\displaystyle\sum_{k=1}^{20}a_k$ を求めよ．
\end{enumerate}

初項 $3$，公比 $2$ の等比数列 $\{a_n\}$ について，次の問いに答えよ．ただし $\log_{10}2=0.3010$，$\log_{10}3=0.4771$ とする．
\begin{enumerate}
  \item $a_n>10^{10}$ となる最小の自然数 $n$ を求めよ．
  \item $b_n=\log_2\dfrac{a_n}{3}$ とするとき，$\displaystyle\sum_{k=1}^{n}b_k$ を $n$ の式で表せ．
\end{enumerate}

$0\leqq\theta\leqq\pi$ のとき，$f(\theta)=2\cos3\theta-3\cos2\theta+6\cos\theta$ について，次の問いに答えよ．
\begin{enumerate}
  \item $t=\cos\theta$ とおくとき，$f(\theta)$ を $t$ の式で表せ．
  \item $f(\theta)$ の最大値と最小値を求めよ．
\end{enumerate}

自然数 $n$ に対し，放物線 $y=x^2-nx$ と $x$ 軸で囲まれた部分の面積を $S_n$ とする．
\begin{enumerate}
  \item $S_n$ を $n$ の式で表せ．
  \item $\displaystyle\sum_{k=1}^{n}S_k$ を $n$ の式で表し，$\displaystyle\sum_{k=1}^{10}S_k$ を求めよ．
\end{enumerate}

1から100までの整数から異なる2つを選ぶ（順序は考えない）．
\begin{enumerate}
  \item 選んだ2数の積が3の倍数となる選び方は何通りか．
  \item 選んだ2数の和が3の倍数となる選び方は何通りか．
\end{enumerate}

$\angle\mathrm{XOY}=60^\circ$ の2辺 OX，OY の両方に接する円 $C_1,C_2,C_3,\cdots$ があり，$C_{n+1}$ は $C_n$ と外接し，$C_n$ より頂点 O に近い側にある．$C_1$ の半径を $1$ とし，$C_n$ の半径を $r_n$ とする．
\begin{enumerate}
  \item $r_n$ を $n$ の式で表せ．
  \item $C_1$ から $C_n$ までの円の面積の和を $n$ の式で表せ．
\end{enumerate}
